<?php
require_once __DIR__.'/Database.php'; require_once __DIR__.'/Finance.php'; require_once __DIR__.'/Repository.php';
final class App {
 private static array $months=['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre'];
 private static function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
 public static function run():void{if(session_status()!==PHP_SESSION_ACTIVE)session_start();$db=Database::connection();$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';if($_SERVER['REQUEST_METHOD']==='POST')self::post($db);self::page($db,$path);}
 private static function post(PDO $db):void{$a=$_POST['action']??'';$notice='';try{if($a==='participant'){$s=$db->prepare('INSERT INTO participants(document,full_name,phone,email) VALUES(?,?,?,?)');$s->execute([trim($_POST['document']),trim($_POST['full_name']),trim($_POST['phone']??''),trim($_POST['email']??'')]);}elseif($a==='contribution'){$p=(int)$_POST['participant_id'];$y=(int)$_POST['year'];$m=(int)$_POST['month'];(new Repository($db))->recordContribution($p,$y,$m,(float)($_POST['amount']??0));$notice='contribution_saved';if($m===11){$q=$db->prepare('SELECT COUNT(*) FROM contributions WHERE participant_id=? AND year=? AND amount_paid<amount_due');$q->execute([$p,$y]);if((int)$q->fetchColumn()===0)$notice='paz_salvo';}}elseif($a==='reset_contribution'){(new Repository($db))->resetContribution((int)$_POST['participant_id'],(int)$_POST['year'],(int)$_POST['month']);}}catch(Throwable $e){$_SESSION['flash']=['error',$e->getMessage()];}$url=$_SERVER['REQUEST_URI'];$url.=str_contains($url,'?')?'&':'?';header('Location: '.$url.($notice?'notice='.$notice:''));exit;}
 private static function page(PDO $db,string $path):void{$year=(int)($_GET['year']??date('Y'));$search=trim($_GET['participant']??$_GET['search']??'');$status=$_GET['status']??'';$repo=new Repository($db);$ps=$repo->participants($search,$path==='/participants'&&in_array($status,['active','inactive'],true)?$status==='active':null);$active=array_values(array_filter($ps,fn($p)=>(int)$p['active']===1));$ls=$repo->loans($status,$search);$title=$path==='/'?'Ahorros':(str_contains($path,'participants')?'Participantes':(str_contains($path,'loans')?'Préstamos':'Reportes'));echo self::head($title);echo self::nav();echo '<main>';if($path==='/')self::savings($db,$active,$year,$search);elseif($path==='/participants')self::participants($ps,$search,$status);elseif($path==='/loans')self::loans($ls,$active,$search,$status);else self::report($db,$year);echo '</main>'.self::foot();}
 private static function nav():string{return '<nav><div class="brand"><span class="brand-mark">₦</span><span>Natillera <small>FINANCIERA</small></span></div><div class="nav-links"><a href="/">Ahorros</a><a href="/participants">Participantes</a><a href="/loans">Préstamos</a><a href="/reports/annual">Reportes</a></div><div class="secure"><span class="dot"></span> Sistema seguro</div></nav>';}
 private static function savings(PDO $db,array $ps,int $year,string $search):void{$q=$db->prepare('SELECT * FROM contributions WHERE year=?');$q->execute([$year]);$by=[];foreach($q as $c)$by[$c['participant_id'].'-'.$c['month']]=$c;echo '<section class="section-title"><div><span class="eyebrow">GESTIÓN DE AHORROS</span><h1>Control de cuotas '.$year.'</h1><p class="muted">Seguimiento de aportes mensuales de la natillera</p></div><div class="fee-badge"><small>Cuota mensual</small><strong>$100.000</strong></div></section><form class="inline filters" method="get"><label>Periodo</label><input name="year" type="number" value="'.$year.'"><input name="participant" value="'.self::e($search).'" placeholder="Buscar por nombre o documento"><button>Filtrar</button></form><div class="payment-help"><span class="status pending">·</span> Pendiente <span class="status partial">½</span> Pago parcial <span class="status complete">✓</span> Completa</div><div class="table-card"><table><thead><tr><th class="participant-header">PARTICIPANTE</th>';for($m=1;$m<=11;$m++)echo '<th>'.self::$months[$m].'</th>';echo '</tr></thead><tbody>';foreach($ps as $p){echo '<tr><td class="participant-cell"><span class="avatar">'.strtoupper(substr($p['full_name'],0,1)).'</span><div class="participant-info"><strong>'.self::e($p['full_name']).'</strong><span><b>Documento</b> '.self::e($p['document']).'</span><span>'.self::e($p['phone']??'').'</span></div></td>';for($m=1;$m<=11;$m++){$c=$by[$p['id'].'-'.$m]??null;$paid=(float)($c['amount_paid']??0);$due=(float)($c['amount_due']??100000);$state=$paid<=0?'pending':($paid<$due?'partial':'complete');echo '<td><form class="contribution-form" method="post" data-month="'.self::$months[$m].'" data-paid="'.$paid.'" data-due="'.$due.'"><input type="hidden" name="action" value="contribution"><input type="hidden" name="participant_id" value="'.$p['id'].'"><input type="hidden" name="year" value="'.$year.'"><input type="hidden" name="month" value="'.$m.'"><button class="status '.$state.'">'.($state==='complete'?'✓':($state==='partial'?'½':'·')).'</button><span class="amount-status">$'.number_format($paid,0,',','.').' / $'.number_format($due,0,',','.').'</span><input name="amount" type="number" placeholder="Abono"><button class="save-btn">Guardar</button></form><form class="reset-form" method="post" data-month="'.self::$months[$m].'" data-paid="'.$paid.'"><input type="hidden" name="action" value="reset_contribution"><input type="hidden" name="participant_id" value="'.$p['id'].'"><input type="hidden" name="year" value="'.$year.'"><input type="hidden" name="month" value="'.$m.'"><button class="reset-btn">Reiniciar</button></form></td>'; }echo '</tr>';}echo '</tbody></table></div>';}
 private static function participants(array $ps,string $search,string $status):void{echo '<section class="section-title"><div><span class="eyebrow">GESTIÓN DE PERSONAS</span><h1>Participantes</h1><p class="muted">Crea, consulta, actualiza y administra el estado de los participantes.</p></div><button>＋ Agregar participante</button></section><form class="people-filter" method="get"><input name="search" value="'.self::e($search).'" placeholder="Nombre, documento o teléfono"><select name="status"><option value="">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button>Aplicar filtros</button></form><div class="table-card"><table><thead><tr><th>Estado</th><th>Participante</th><th>Documento</th><th>Contacto</th><th>Acciones</th></tr></thead><tbody>';foreach($ps as $p)echo '<tr><td><span class="person-status '.((int)$p['active']?'active':'inactive').'">'.((int)$p['active']?'Activo':'Inactivo').'</span></td><td><strong>'.self::e($p['full_name']).'</strong></td><td>'.self::e($p['document']).'</td><td>'.self::e($p['phone']?:'—').'<br>'.self::e($p['email']?:'—').'</td><td><a class="action-link" href="/participants">Editar</a></td></tr>';echo '</tbody></table></div>';}
 private static function loans(array $ls,array $ps,string $search,string $status):void{echo '<section class="section-title"><div><span class="eyebrow">GESTIÓN DE PRÉSTAMOS</span><h1>Préstamos</h1><p class="muted">Consulta, actualiza y cancela préstamos conservando su historial.</p></div></section><form class="filters" method="get"><input name="participant" value="'.self::e($search).'" placeholder="Filtrar por participante, referido o documento"><select name="status"><option value="">Todos los estados</option><option value="active">Activos</option><option value="paid">Pagados</option><option value="cancelled">Cancelados</option></select><button>Filtrar</button></form><section class="card loan-create"><h2>Registrar préstamo</h2><form method="post"><input type="hidden" name="action" value="loan_create"><select name="participant_id" required><option value="">Participante responsable</option>';foreach($ps as $p)echo '<option value="'.$p['id'].'">'.self::e($p['full_name']).'</option>';echo '</select><select name="loan_type"><option value="PARTICIPANT">Al participante · 5%</option><option value="REFERRED">A referido · 10%</option></select><input name="referred_name" placeholder="Nombre del referido"><input name="referred_document" placeholder="Identificación del referido"><input name="principal" type="number" min="1" step="0.01" placeholder="Monto" required><input name="term_months" type="number" min="1" max="60" placeholder="Meses" required><input name="start_date" type="date" required><button>Crear préstamo</button></form></section><div class="table-card"><table><thead><tr><th>Responsable</th><th>Beneficiario</th><th>Monto</th><th>Tasa</th><th>Plazo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';foreach($ls as $l){$benef=($l['loan_type']??'PARTICIPANT')==='REFERRED'?self::e($l['referred_name']??'Referido'):'El participante';$state=$l['status']==='paid'?'✓ Pagado':($l['status']==='active'?'● Activo':'Cancelado');echo '<tr><td>'.self::e($l['full_name']).'</td><td>'.$benef.'</td><td>$'.number_format($l['principal'],0,',','.').'</td><td>'.((float)$l['monthly_rate']*100).'%</td><td>'.$l['term_months'].' meses</td><td><span class="loan-state '.self::e($l['status']).'">'.$state.'</span></td><td><a class="action-btn eye" href="/loans/'.$l['id'].'">◉ Ver plan</a>'.($l['status']==='active'?'<button class="action-btn edit" type="button">✎ Editar</button><button class="action-btn cancel" type="button">⊘ Cancelar préstamo</button>':'').'</td></tr>';}echo '</tbody></table></div>';}
 private static function report(PDO $db,int $year):void{$r=(new Repository($db))->annualReport($year);echo '<section class="report-hero"><div><span class="eyebrow">CIERRE ANUAL · PRIMERA SEMANA DE DICIEMBRE</span><h1>Reporte financiero '.$year.'</h1><p class="muted">Resumen del ahorro acumulado y las ganancias generadas por todos los préstamos.</p></div><div class="report-badge">Distribución igualitaria</div></section><form class="report-filter" method="get"><div><label for="year">Año del cierre</label><input id="year" name="year" type="number" value="'.$year.'"></div><button>Consultar año</button></form><div class="report-stats"><div class="report-stat green"><small>Participantes activos</small><strong>'.count($r['rows']).'</strong></div><div class="report-stat blue"><small>Intereses consolidados</small><strong>$'.number_format($r['total_interest'],0,',','.').'</strong></div><div class="report-stat purple"><small>Ganancia igual por participante</small><strong>$'.number_format($r['share'],0,',','.').'</strong></div></div><div class="report-table"><table><thead><tr><th>Participante</th><th>Ahorro 11 meses</th><th>Préstamos propios</th><th>Préstamos a referidos</th><th>Interés generado</th><th>Parte igual</th><th>Total a entregar</th></tr></thead><tbody>';foreach($r['rows'] as $x)echo '<tr><td><strong>'.self::e($x['participant']['full_name']).'</strong><small>'.self::e($x['participant']['document']).'</small></td><td>$'.number_format($x['savings'],0,',','.').'</td><td>'.($x['own_count']??0).'</td><td>'.($x['referred_count']??0).'</td><td>$'.number_format($x['interest_generated'],0,',','.').'</td><td class="share">$'.number_format($x['interest_share'],0,',','.').'</td><td class="money">$'.number_format($x['savings']+$x['interest_share'],0,',','.').'</td></tr>';echo '</tbody></table></div><section class="method"><button class="method-toggle">ⓘ ¿Cómo se calcula?</button><div class="method-popover">Se suman los intereses de las cuotas con vencimiento dentro del año consultado, tanto de préstamos propios al 5% como de préstamos a referidos al 10%. La ganancia total se divide en partes iguales entre los participantes activos y se suma al ahorro individual de enero a noviembre.</div></section>';}
 private static function head(string $title):string{return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Natillera</title><link rel="manifest" href="/static/manifest.webmanifest"><link rel="apple-touch-icon" href="/static/icons/icon.svg"><link rel="stylesheet" href="/static/app.css"><link rel="stylesheet" href="/static/pwa.css"><link rel="stylesheet" href="/static/contacts.css"><link rel="stylesheet" href="/static/contact-fix.css"><link rel="stylesheet" href="/static/v2.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head><body>';}
 private static function foot():string{return '<script src="/static/pwa.js" defer></script><script src="/static/v2.js" defer></script><script>document.addEventListener("DOMContentLoaded",function(){var n=new URLSearchParams(location.search).get("notice"),m={contribution_saved:"Aporte guardado correctamente.",paz_salvo:"Participante a paz y salvo con sus ahorros.",loan_created:"Préstamo creado correctamente.",loan_updated:"Préstamo y plan de pagos actualizados.",loan_cancelled:"Préstamo cancelado correctamente."};if(n&&m[n]&&window.Swal)Swal.fire({toast:true,position:"top-end",icon:"success",title:m[n],showConfirmButton:false,timer:3200,timerProgressBar:true})});if("serviceWorker" in navigator)navigator.serviceWorker.register("/static/sw.js")</script></body></html>';}
}
